-- 게임 기준 데이터를 캐릭터 / 무기 / 에코 / 에코 세트 4개 테이블로 다시 정리합니다.
-- V4(정규화 테이블 16개)와 V5(chara_info, JSONB)는 지우고, 각 테이블에는 기본 정보만 담습니다.
-- 보너스 목록·유효 옵션·세트 효과·추천 데이터는 넣지 않습니다(스키마 재검토 후 추가).
-- 데이터는 프론트 src/config/ 에서 생성했습니다. status: ACTIVE(공개) / HIDDEN(숨김) / UPCOMING(출시 예정)

DROP TABLE IF EXISTS
    chara_info,
    character_valid_options, character_echo_combo_parts, character_echo_combos, character_recommended_weapons,
    echo_set_main_echoes, main_echo_character_descriptions, main_echo_character_bonuses, main_echo_bonuses,
    main_echoes, echo_set_effect_bonuses, echo_set_effects, echo_sets, weapon_bonuses, weapons,
    character_innate_bonuses, character_base_stats, characters;

CREATE TABLE chara_info (
    id VARCHAR(50) PRIMARY KEY,
    name VARCHAR(100) NOT NULL,
    rarity SMALLINT NOT NULL CHECK (rarity BETWEEN 1 AND 5),
    element VARCHAR(10) NOT NULL,
    weapon_type VARCHAR(10),
    image_path VARCHAR(255),
    base_hp NUMERIC(10, 2),
    base_atk NUMERIC(10, 2),
    base_def NUMERIC(10, 2),
    base_energy_regen NUMERIC(6, 2),
    base_crit_rate NUMERIC(6, 2),
    base_crit_dmg NUMERIC(6, 2),
    status VARCHAR(10) NOT NULL DEFAULT 'ACTIVE' CHECK (status IN ('ACTIVE', 'HIDDEN', 'UPCOMING')),
    sort_order INT NOT NULL
);

CREATE TABLE weapon_info (
    id VARCHAR(50) PRIMARY KEY,
    name VARCHAR(100) NOT NULL,
    type VARCHAR(10) NOT NULL,
    icon_path VARCHAR(255),
    atk NUMERIC(8, 2) NOT NULL,
    sub_stat VARCHAR(50),
    sub_stat_value NUMERIC(8, 2),
    passive_name VARCHAR(100),
    description TEXT,
    status VARCHAR(10) NOT NULL DEFAULT 'ACTIVE' CHECK (status IN ('ACTIVE', 'HIDDEN', 'UPCOMING')),
    sort_order INT NOT NULL
);

CREATE TABLE echo_info (
    id VARCHAR(80) PRIMARY KEY,
    name VARCHAR(100) NOT NULL,
    icon_path VARCHAR(255),
    description TEXT,
    passive_description TEXT,
    status VARCHAR(10) NOT NULL DEFAULT 'ACTIVE' CHECK (status IN ('ACTIVE', 'HIDDEN', 'UPCOMING')),
    sort_order INT NOT NULL
);

CREATE TABLE echo_set_info (
    id VARCHAR(50) PRIMARY KEY,
    name VARCHAR(100) NOT NULL,
    icon_path VARCHAR(255),
    status VARCHAR(10) NOT NULL DEFAULT 'ACTIVE' CHECK (status IN ('ACTIVE', 'HIDDEN', 'UPCOMING')),
    sort_order INT NOT NULL
);





